# -*- coding: utf-8 -*-
"""دفعة المقالات 2أ — تحديث 8 مقالات من البيانات الموثقة (sources-log.md 30/9/2026)
Atomic patch: يفشل كله أو ينفع كله — بدون تعديل جزئي.
المصادر: أقسام تجديد رخصة السيارة + التسجيل الضريبي + الجوازات + شهادة الميلاد (قيد المواليد)
+ التأمين الصحي الشامل + رخصة قيادة جديدة + العقارات (بيع/رهن/إيجار)."""
import re, sys, shutil

PATH = "articles.html"
BAK = "articles.html.bak-batch2a"

UPDATES = {
    "إزاي تتجدد رخصة سيارتك؟":
        r"""<h3>📋 الخطوات (أونلاين)</h3><p>1. سجّل الدخول على <a href=\"https://digital.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> واختار خدمة «مركباتي»</p><p>2. استعلم عن السيارة برقم اللوحة والشاسيه</p><p>3. دوس «تجديد» وسدد كل الرسوم والمخالفات إلكترونيًا</p><p>4. هيوصلك رسالة SMS بالتفعيل</p><p>5. الاستلام خلال 10 أيام عمل أو التوصيل للمنزل</p><h3>✅ شروط التجديد الإلكتروني</h3><p>• للسيارات الملاكية والدراجات النارية حتى 2030cc</p><p>• سداد كل الرسوم والمخالفات — وملصق إلكتروني</p><p>• مفيش حظر مروري ولا فحص فني مطلوب</p><h3>💰 الرسوم بالبنود</h3><p>كشف طبي 385ج + استمارة 115ج + ملف 65ج + نموذج 265 بـ45ج + طابع 15ج + شهادة مخالفات 120ج + ملصق 150ج + لوحات ~350ج + الضريبة حسب سعة المحرك من 225ج حتى 3000ج</p><p>إجمالي تجديد 3 سنين للسيارة الملاكية: 4000-6000 جنيه</p><h3>⏰ مهم!</h3><p>في مهلة سماح 30 يوم بعد انتهاء الرخصة — وفي وحدات مرور إلكترونية بالمولات بالحجز المسبق والدفع اللانقدي</p>""",
    "إزاي تسجل في الضريبة؟":
        r"""<h3>📋 الخطوات</h3><p>1. التسجيل إلزامي خلال 30 يوم من بدء مزاولة النشاط أو الخضوع للقيمة المضافة (م.25 من قانون الإجراءات الضريبية الموحد 206/2020)</p><p>2. قدّم نموذج 1/2 تسجيل يدويًا أو إلكترونيًا من <a href=\"https://eta.gov.eg\" target=\"_blank\">eta.gov.eg</a> — النسخة الإلكترونية ليها حجية الإثبات</p><p>3. لو الطلب ناقص هتتخطر لتستوفيه خلال 15 يوم</p><p>4. استلم الرقم الضريبي والبطاقة الضريبية</p><h3>💰 الرسوم</h3><p>غير المكلفين تحت حد التسجيل: رسم سنوي بحد أقصى 500 جنيه (المحدد فعليًا 325 جنيه) وبيقف عند بلوغ الحد</p><h3>⏰ مهم!</h3><p>• صلاحية البطاقة الضريبية 5 سنين</p><p>• لو ما سجلتش، المأمورية ممكن تسجّلك من تلقاء نفسها وتخطورك خلال 5 أيام عمل — والتقصير مش بيسقط المسؤولية</p><h3>📞 القنوات والاستفسار</h3><p>المنظومة الإلكترونية والمكاتب الأمامية والمأمورية المختصة — الخط الساخن 16395</p>""",
    "إزاي تستخرج جواز السفر؟":
        r"""<h3>📋 الخطوات</h3><p>1. قدّم طلبك من دليل خدمات الجوازات الإلكتروني <a href=\"https://enationality.moi.gov.eg\" target=\"_blank\">enationality.moi.gov.eg</a> أو احجز موعد من <a href=\"https://egpassport.gov.eg\" target=\"_blank\">egpassport.gov.eg</a> وروح لمكتب الجوازات</p><p>2. املا نموذج 29 جوازات (مجاني) وسجّل البيانات وخد البصمة</p><p>3. ادفع الرسوم</p><p>4. الاستلام: عادي 3-15 يوم عمل — مستعجل 48 ساعة — عاجل نفس اليوم</p><h3>💰 الرسوم (قرار وزير الداخلية 1104/2025 من 1/7/2025)</h3><p>• الرسم الأساسي 500 جنيه</p><p>• الإجمالي الفعلي: عادي ~1200-1400 جنيه — مستعجل ~1725 جنيه — VIP ~2950 جنيه</p><p>• بدل فاقد/تالف ~1510 جنيه (رسم أساسي مضاعف 1000 جنيه)</p><h3>📄 المستندات (فوق 16 سنة)</h3><p>• بطاقة الرقم القومي سارية</p><p>• 4 صور 4×6 بخلفية بيضاء</p><p>• موقف التجنيد للذكور</p><p>• وثيقة الزواج أو الطلاق للإناث</p><p>• قيد دراسي للطلاب</p><h3>🧸 للأطفال دون 16 سنة</h3><p>شهادة ميلاد مميكنة + جوازا الوالدين + قيد عقد الزواج + حضور أحد الوالدين</p><h3>⏰ صلاحية الجواز</h3><p>7 سنين — ومفيش مرافقين بيتضافوا عليه</p>""",
    "إزاي تتجدد جواز السفر؟":
        r"""<h3>📋 الخطوات</h3><p>1. التقديم من دليل خدمات الجوازات الإلكتروني <a href=\"https://enationality.moi.gov.eg\" target=\"_blank\">enationality.moi.gov.eg</a> أو حجز موعد من <a href=\"https://egpassport.gov.eg\" target=\"_blank\">egpassport.gov.eg</a></p><p>2. روح لمكتب الجوازات في الموعد وسلّم الجواز القديم</p><p>3. املا نموذج 29 جوازات (مجاني) وسجّل البيانات الجديدة</p><p>4. ادفع الرسوم: الرسم الأساسي 500 جنيه — الإجمالي الفعلي: عادي ~1200-1400 جنيه / مستعجل ~1725 جنيه</p><p>5. الاستلام: عادي 3-15 يوم عمل — مستعجل 48 ساعة — عاجل نفس اليوم</p><h3>📄 المستندات</h3><p>• الجواز القديم</p><p>• بطاقة الرقم القومي سارية</p><p>• 4 صور 4×6 بخلفية بيضاء</p><p>• موقف التجنيد للذكور — ووثيقة الزواج/الطلاق للإناث</p><h3>⏰ مهم!</h3><p>• الجواز صلاحيته 7 سنين</p><p>• لو البطاقة منتهية: فيه جواز مؤقت صلاحيته 3 سنين</p><h3>🌍 من الخارج</h3><p>التجديد عبر القنصليات المصرية والمدة أطول (6-8 أسابيع)</p>""",
    "إزاي تسجّل مولود جديد؟":
        r"""<h3>📋 الخطوات</h3><p>1. خد إخطار الولادة من المستشفى أو الطبيب</p><p>2. بلّغ عن المولود لمكتب الصحة خلال 15 يوم من الولادة</p><p>3. قيّد المولود في السجل المدني واستلم شهادة الميلاد المميكنة (أول مرة 45 جنيه)</p><p>4. النسخ الإضافية: نموذج 40 من السجل المدني (مكررة 25 جنيه) أو أونلاين من <a href=\"https://digital.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> (65 جنيه أول مرة + 60 جنيه لكل نسخة إضافية)</p><h3>📄 المستندات</h3><p>• إخطار الولادة من المستشفى/مكتب الصحة</p><p>• بطاقة الرقم القومي للأب والأم</p><p>• عقد الزواج</p><h3>⏰ مهم!</h3><p>• التبليغ خلال 15 يوم من الولادة (مكتب الصحة)</p><p>• المواليد في الخارج: التسجيل خلال 3 شهور من القنصلية المصرية</p>""",
    "إزاي تسجّل في التأمين الصحي؟":
        r"""<h3>📋 الخطوات</h3><p>1. سجّل بيانات أسرتك التأمينية أونلاين من <a href=\"https://digital.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a> — اختار المحافظة حسب البطاقة واحفظ</p><p>2. بعد 48 ساعة روح لوحدة الرعاية الأولية لسداد الاشتراك واستلام الكارت برقم الملف العائلي</p><p>3. اعمل الفحص المبدئي وافتح الملف العائلي</p><h3>👥 مين بيسجل إزاي؟</h3><p>• غير الخاضعين للتأمينات: من مكتب خدمة العملاء لبيانات الدخل والسداد الذاتي</p><p>• الغير قادرين: الدولة بتسدد عنهم</p><h3>📍 المحافظات المتاحة</h3><p>• المرحلة الأولى: بورسعيد، الأقصر، الإسماعيلية، جنوب سيناء، السويس، أسوان</p><p>• المرحلة الثانية: دمياط، كفر الشيخ، المنيا، مطروح، شمال سيناء</p><h3>💡 المميزات</h3><p>تغطية من الولادة للوفاة + مساهمات رمزية على الأدوية والأشعة والتحاليل (والمعفيون منها: الغير قادرين وأصحاب الأمراض المزمنة والأورام)</p><h3>🔄 خدمات تانية</h3><p>• إضافة مولود: شهادة ميلاد مميكنة + أصل كارت الأسرة</p><p>• النقل بين المحافظات: إفادة إغلاق الملف السابق</p>""",
    "إزاي تستخرج رخصة قيادة جديدة؟":
        r"""<h3>📋 الخطوات</h3><p>1. افتح ملف رخصة القيادة في وحدة المرور</p><p>2. اعمل الكشف الطبي (نظر وباطنة وفصيلة الدم) وتحليل المخدرات من جهة معتمدة</p><p>3. عدّي الاختبار النظري للإشارات</p><p>4. عدّي الاختبار العملي</p><p>5. سدد الرسوم — والاستلام خلال 10-14 يوم عمل</p><h3>📄 المستندات</h3><p>• بطاقة الرقم القومي</p><p>• المؤهل الدراسي أو إفادة القيد</p><p>• 4 صور 4×6</p><p>• نموذج 256</p><p>• شهادة طبية (نظر/باطنة/فصيلة دم)</p><p>• تحليل مخدرات معتمد</p><h3>💰 التكلفة</h3><p>1140-1500 جنيه إجمالية</p><h3>⏰ السن والصلاحية</h3><p>• الرخصة الخاصة: من 18 سنة — صلاحيتها 10 سنين</p><p>• الرخصة المهنية: من 21 سنة — بصلاحية أقصر</p>""",
    "إزاي تسجّل عقد في الشهر العقاري؟":
        r"""<h3>📋 إيه اللي بيسجل عندك؟</h3><p>• عقد بيع عقار: الرسم الأساسي من 500 جنيه (حتى 3900 جنيه لمساحة أقل من 300م) — المدة القصوى 37 يوم — ورسالة SMS بموقف الطلب خلال 24 ساعة</p><p>• رهن عقاري: لا ينعقد الرهن الرسمي إلا بورقة رسمية + القيد بالمأمورية المختصة + الرسوم على قيمة الدين — وفك الرهن بمخالصة موثقة</p><p>• عقد إيجار: رسوم 20 جنيه + رسم نسبي 0.5% (بحد أدنى 10 جنيه) — والتوثيق خلال 24 ساعة</p><h3>📄 المستندات</h3><p>• عقد البيع: رفع مساحي معتمد + رخصة + سند الملكية</p><p>• عقد الإيجار: أصل العقد + بطاقتان ساريتان + حضور الطرفين</p><h3>💡 نصيحة</h3><p>• حجز المعاد للتوثيق متاح عبر <a href=\"https://digital.gov.eg\" target=\"_blank\">بوابة مصر الرقمية</a></p><p>• في سيارة توثيق متنقلة بـ500 جنيه على الرقم 01555559875</p>""",
}

src = open(PATH, encoding="utf-8").read()
shutil.copyfile(PATH, BAK)
count_before = src.count("title:'")
problems = []
for title, new_content in UPDATES.items():
    esc = re.escape(title)
    pattern = re.compile(r"(title:'" + esc + r"'.*?content:`)[^`]*(`)", re.DOTALL)
    if len(pattern.findall(src)) != 1:
        problems.append(title); continue
    src = pattern.sub(lambda m: m.group(1) + new_content + m.group(2), src, count=1)

# إصلاح خطأ مطبعي في مقدمة مقال رخصة السيارة
if src.count("رخرة السيارة") != 1:
    problems.append("(typo: رخرة)")
else:
    src = src.replace("رخرة السيارة", "رخصة السيارة")

if problems:
    open(PATH, "w", encoding="utf-8").write(open(BAK, encoding="utf-8").read())
    sys.exit("فشل التطابق لـ: " + ", ".join(problems) + " — تم التراجع")

if src.count("title:'") != count_before or src.count("content:`") != count_before:
    sys.exit("عدد المقالات اتغير! — لم يتم الحفظ")

open(PATH, "w", encoding="utf-8").write(src)
checks = ["مركباتي", "قانون الإجراءات الضريبية الموحد 206/2020", "قرار وزير الداخلية 1104/2025",
          "جواز مؤقت", "خلال 15 يوم من الولادة", "بعد 48 ساعة", "1140-1500", "المدة القصوى 37 يوم"]
print("OK — تم تحديث 8 مقالات + إصلاح الخطأ المطبعي. عدد المقالات الكلي:", count_before)
for c in checks:
    print(("✓ " if c in src else "✗ مفقود ") + c)
print("✓ الخطأ المطبعي اتصلح" if "رخرة" not in src else "✗ الخطأ لسه موجود")
